insert into public.tabacos (id, nombre, marca, pais, tipo, corte, formato, descripcion, fuerza, notas, foto, hojas) values
('2362','Virginia Mellow','MyRott','Argentina','Virginia','Ribbon','50 g','Virginia Mellow es una mezcla de la familia Virginia de MyRott, cortado en tiras finas (ribbon). Lleva virginia y burley. Virginias y burley de Salta y Tucumán en corte grueso; suave y dulce, pensada para empezar. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley']::text[]),
('2363','Black Intense','MyRott','Argentina','Inglesa','Ribbon','50 g','Black Intense es una mezcla de estilo inglés de MyRott, cortado en tiras finas (ribbon). Lleva virginia, burley, latakia y perique. De estilo inglés, con criollo y tabaco de cuerda en la base y virginia lemon que aporta dulzor. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Latakia', 'Perique']::text[]),
('2364','Original Flavour','MyRott','Argentina','Aromática','Ribbon','50 g','Original Flavour es una mezcla aromática de MyRott, cortado en tiras finas (ribbon). Lleva virginia. Dos tercios de hoja oscura fermentada al calor y un tercio de virginia lemon. Dulce y especiado, con aroma de clavo. Formato: 50 g.',0,'{}'::text[],'',array['Virginia']::text[]),
('2365','Lakeland Juliet Rose','MyRott','Argentina','Lakeland','Ribbon','50 g','Lakeland Juliet Rose es una mezcla de estilo Lakeland de MyRott, cortado en tiras finas (ribbon). Lleva virginia. Varias virginias con un aderezo floral y frutal; notas de tierra, hierba, frutos negros y cítricos. Formato: 50 g.',0,'{}'::text[],'',array['Virginia']::text[]),
('2366','Black Frog','MyRott','Argentina','Inglesa','Ribbon','50 g','Black Frog es una mezcla de estilo inglés de MyRott, cortado en tiras finas (ribbon). Lleva virginia, burley y latakia. Inglesa intensa: más de la mitad es hoja con latakia, sobre burley y virginias, una de ellas con más de 12 años de bodega. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Latakia']::text[]),
('2367','Half & Half Christmas','MyRott','Argentina','Aromática','Ribbon','50 g','Half & Half Christmas es una mezcla aromática de MyRott, cortado en tiras finas (ribbon). Lleva virginia, burley y perique. Aroma de pan de Navidad: pasas, canela, cardamomo, clavo y azahar, con un toque de perique. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Perique']::text[]),
('2368','Pipa Club Cañada de Gómez','MyRott','Argentina','Aromática','Flake','50 g','Pipa Club Cañada de Gómez es una mezcla aromática de MyRott, prensado y cortado en láminas (flake). Lleva virginia y burley. Virginias y burley con más de 10 años de bodega; aroma afrutado, cítrico y floral con vainilla. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley']::text[]),
('2369','Vaper Gondor Grass Flake','MyRott','Argentina','Aromática','Flake','50 g','Vaper Gondor Grass Flake es una mezcla aromática de MyRott, prensado y cortado en láminas (flake). Aroma de bizcocho de frutas: jengibre, cítricos, ron, haba tonka y un final de chocolate. Formato: 50 g.',0,'{}'::text[],'',array[]::text[]),
('2370','Dark Bite Mixture','MyRott','Argentina','Aromática','Flake','50 g','Dark Bite Mixture es una mezcla aromática de MyRott, prensado y cortado en láminas (flake). Lleva virginia, burley, orientales, perique y cavendish. Con criollo curado al sol; aroma de pasas, higos y nueces, a la manera de los viejos plugs irlandeses. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Oriental', 'Perique', 'Cavendish']::text[]),
('2371','Revolution Mixture','MyRott','Argentina','Aromática','Flake','50 g','Revolution Mixture es una mezcla aromática de MyRott, prensado y cortado en láminas (flake). Lleva virginia, burley y cavendish. Burley añejo, virginias y criollo con tabaco de cuerda, ámbar gris y aroma de tabaco negro francés. Bastante fuerte. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Cavendish']::text[]),
('2372','Widow''s Sons Mixture','MyRott','Argentina','Virginia','Flake','50 g','Widow''s Sons Mixture es una mezcla de la familia Virginia de MyRott, prensado y cortado en láminas (flake). Lleva virginia y burley. Virginia rojo madurado en torta prensada con vapor, con un poco de burley. Sin aromatizar. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley']::text[]),
('2373','English Mixture','MyRott','Argentina','Inglesa','Broken Flake','50 g','English Mixture es una mezcla de estilo inglés de MyRott, en láminas desmenuzadas (broken flake). Lleva virginia, burley, latakia y cavendish. Burley y criollo con virginias y latakia de Chipre. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Latakia', 'Cavendish']::text[]),
('2374','Wizard Choice','MyRott','Argentina','Aromática','Flake','50 g','Wizard Choice es una mezcla aromática de MyRott, prensado y cortado en láminas (flake). Lleva burley y cavendish. Burley con black cavendish; aroma de chocolate con naranja y un dulzor de ron. Formato: 50 g.',0,'{}'::text[],'',array['Burley', 'Cavendish']::text[]),
('2375','Scottish Mixture','MyRott','Argentina','Aromática','Ready Rubbed','50 g','Scottish Mixture es una mezcla aromática de MyRott, desmenuzado y listo para cargar (ready rubbed). Lleva virginia, burley y cavendish. Con criollo curado al sol y tres virginias; aroma de café tostado. Doble prensado. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Cavendish']::text[]),
('2376','Danish Mixture','MyRott','Argentina','Aromática','Ready Rubbed','50 g','Danish Mixture es una mezcla aromática de MyRott, desmenuzado y listo para cargar (ready rubbed). Lleva virginia, burley y cavendish. De estilo danés, con vainilla, nuez y canela. Doble prensado. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Cavendish']::text[]),
('2377','Kakaw Mixture','MyRott','Argentina','Aromática','Ready Rubbed','50 g','Kakaw Mixture es una mezcla aromática de MyRott, desmenuzado y listo para cargar (ready rubbed). Lleva virginia, burley, kentucky y cavendish. Mucho criollo y burley con cavendish; aroma de chocolate. Doble prensado. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Kentucky', 'Cavendish']::text[]),
('2378','Sunshine Mixture','MyRott','Argentina','Virginia','Ready Rubbed','50 g','Sunshine Mixture es una mezcla de la familia Virginia de MyRott, desmenuzado y listo para cargar (ready rubbed). Lleva virginia y burley. Virginias bright, lemon, rojo y brown con un poco de burley; notas ácidas y cremosas. Doble prensado. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley']::text[]),
('2379','One Eye Deer','MyRott','Argentina','Virginia-Perique','Ribbon','50 g','One Eye Deer es una mezcla de Virginia con perique de MyRott, cortado en tiras finas (ribbon). Lleva virginia y perique. Virginias con perique: cítricos, pan, heno y miel, con especias, higos y ciruelas. Sin aromatizar. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Perique']::text[]),
('2380','St. Patrick''s','MyRott','Argentina','Aromática','Flake','50 g','St. Patrick''s es una mezcla aromática de MyRott, prensado y cortado en láminas (flake). Lleva virginia, burley y cavendish. Con criollo; aroma de amaretto, café y naranja. Formato: 50 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Cavendish']::text[]),
('2381','Stone Cabin','MyRott','Argentina','Virginia','Flake','Lata de 70 g','Stone Cabin es una mezcla de la familia Virginia de MyRott, prensado y cortado en láminas (flake). Lleva virginia, burley y cavendish. Virginias bright y rojo con burley y cavendish, madurado; notas de madera, frutos secos y pan tostado. Formato: lata de 70 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Cavendish']::text[]),
('2382','Aged Burley Flake','MyRott','Argentina','Burley','Flake','Lata de 70 g','Aged Burley Flake es una mezcla de la familia Burley de MyRott, prensado y cortado en láminas (flake). Lleva burley. Tres burleys argentinos, uno con 12 años de bodega, tostados y prensados; notas de nuez pecana, tierra y café. Formato: lata de 70 g.',0,'{}'::text[],'',array['Burley']::text[]),
('2383','Amber Peel','MyRott','Argentina','Aromática','Flake','Lata de 70 g','Amber Peel es una mezcla aromática de MyRott, prensado y cortado en láminas (flake). Lleva virginia, burley y latakia. Burley con virginias y un toque de latakia argentina; aroma de chocolate y naranja. Formato: lata de 70 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Latakia']::text[]),
('2384','Malvinas Plug','MyRott','Argentina','Virginia-Perique','Plug','Lata de 70 g','Malvinas Plug es una mezcla de Virginia con perique de MyRott, prensado en barra (plug). Lleva virginia, burley y perique. Virginia rojo y brillante con burley y perique, prensado en barra. Formato: lata de 70 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Perique']::text[]),
('2385','Wagner','MyRott','Argentina','Aromática','Flake','Lata de 70 g','Wagner es una mezcla aromática de MyRott, prensado y cortado en láminas (flake). Lleva virginia, burley, latakia, perique y cavendish. Virginias rojo y brillante con cavendish aromatizado de cereza negra, perique, burley y un toque de latakia. Formato: lata de 70 g.',0,'{}'::text[],'',array['Virginia', 'Burley', 'Latakia', 'Perique', 'Cavendish']::text[]),
('2386','Sherlock Full Virginia Flake','MyRott','Argentina','Virginia','Broken Flake','Lata de 70 g','Sherlock Full Virginia Flake es una mezcla de la familia Virginia de MyRott, en láminas desmenuzadas (broken flake). Lleva virginia. Solo virginias, prensadas, fermentadas y desmenuzadas; con un toque de vainilla y haba tonka. Formato: lata de 70 g.',0,'{}'::text[],'',array['Virginia']::text[]),
